#include <bits/stdc++.h>
using namespace std;
#define ll long long 
#define endl "\n"

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
    int t;
    cin >> t;
    while(t--){
        int n,k;
        cin >> n >> k;
        string s;
        cin >> s;
        int i;

        for(i=0;i<s.size();i++){
            if(s[i]=='G'){
                break;
            }
        }
        
        int c=0;
        int j;
        for(j=i+1;j<s.size();j++){
            if(s[j]=='G'){
                c++;
            }
            else{
                continue;
            }
            if(c==k){
            break;
            }
        }
        int sum=0;
        int k1;
        for(k1=j+1;k1<s.size();k1++){
            if(s[k1]=='G'){
                break;
            }
        }
        for(int p=k1+1;p<s.size();p++){
            if(s[p]=='G'){
                sum++;
            }
            else{
                sum+=2;
            }
        }
        if(sum>k){
            cout << "NO" << "\n";
        }
        else{
            cout << "YES" << "\n";
        }
        
    }
}
